import{_ as n,a0 as d,w as p,s as o,I as i,x as a,a1 as t,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何清理你的 Ubuntu 14.10/14.04/13.10 系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何清理你的 Ubuntu 14.10/14.04/13.10 系统 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何清理你的 Ubuntu 14.10/14.04/13.10 系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何清理你的 Ubuntu 14.10/14.04/13.10 系统 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150126 Cleaning up Ubuntu 14.10,14.04,13.10 system","title":"如何清理你的 Ubuntu 14.10/14.04/13.10 系统","tag":"201503","desc":""},"relativePath":"201503/20150126 Cleaning up Ubuntu 14.10,14.04,13.10 system.md","filePath":"[post].md"}'),h={name:"201503/20150126 Cleaning up Ubuntu 14.10,14.04,13.10 system.md"};function u(b,e,g,k,c,f){const s=d("Link");return p(),o("div",null,[e[19]||(e[19]=i("h1",{id:"如何清理你的-ubuntu-14-10-14-04-13-10-系统",tabindex:"-1"},[a("如何清理你的 Ubuntu 14.10/14.04/13.10 系统 "),i("a",{class:"header-anchor",href:"#如何清理你的-ubuntu-14-10-14-04-13-10-系统","aria-label":"Permalink to “如何清理你的 Ubuntu 14.10/14.04/13.10 系统”"},"​")],-1)),i("p",null,[e[1]||(e[1]=a("前面我们已经讨论了",-1)),t(s,{href:"http://www.ubuntugeek.com/cleaning-up-all-unnecessary-junk-files-in-ubuntu.html"},{default:l(()=>[...e[0]||(e[0]=[a("如何清理 Ubuntu GNU/Linux 系统",-1)])]),_:1}),e[2]||(e[2]=a("，这篇教程将在原有教程的基础上，增加对新的 Ubuntu 发行版本的支持，并介绍更多的工具。",-1))]),e[20]||(e[20]=r('<p>假如你想清理你的 Ubuntu 主机，你可以按照以下的一些简单步骤来移除所有不需要的垃圾文件。</p><h2 id="移除多余软件包" tabindex="-1">移除多余软件包 <a class="header-anchor" href="#移除多余软件包" aria-label="Permalink to “移除多余软件包”">​</a></h2><p>这又是一个内置功能，但这次我们不必使用新得立包管理软件(Synaptic Package Manager)，而是在终端中达到目的。</p><p>现在，在终端窗口中键入如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get autoclean</span></span></code></pre></div><p>这便激活了包清除命令。这个命令所做的工作是： 自动清除那些当你安装或升级程序时系统所缓存的 <code>.deb</code> 包(即清除 <code>/var/cache/apt/archives</code> 目录，不过只清理过时的包)。如果需要使用清除命令，只需在终端窗口中键入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get clean</span></span></code></pre></div><p>然后你就可以使用自动移除命令。这个命令所做的工作是：清除那些 在系统中被某个已经卸载的软件 作为依赖所安装的软件包。要使用自动移除命令，在终端窗口中键入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get autoremove</span></span></code></pre></div><h2 id="移除不需要的本地化数据" tabindex="-1">移除不需要的本地化数据 <a class="header-anchor" href="#移除不需要的本地化数据" aria-label="Permalink to “移除不需要的本地化数据”">​</a></h2><p>为达到此目的，我们需要安装 <code>localepurge</code> 软件，它将自动移除一些不需要的本地化数据（LCTT 译注：即各种语言翻译）。这个软件是一个简单的脚本，它将从那些不再需要的本地化文件和本地化联机手册( man pages ) 所占用的空间中回收磁盘空间。这个软件将在任何 apt 安装命令运行时 被自动激活。</p><p>在 Ubuntu 中安装 <code>localepurge</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install localepurge</span></span></code></pre></div><p>在通过 <code>apt-get install</code> 安装任意软件后， localepurge 将移除所有不是使用你系统中所设定语言的翻译文件和翻译的联机手册。</p><p>假如你想设置 <code>localepurge</code>，你需要编辑 <code>/ect/locale.nopurge</code> 文件。</p><p>根据你已经安装的软件，这将为你节省几兆的磁盘空间。</p><p>例子：-</p><p>假如我试着使用 <code>apt-get</code> 来安装 <code>dicus</code>软件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install discus</span></span></code></pre></div><p>在软件安装完毕之后，你将看到如下提示：</p><blockquote><p>localepurge: Disk space freed in /usr/share/locale: 41860K</p></blockquote><h2 id="移除孤包" tabindex="-1">移除孤包 <a class="header-anchor" href="#移除孤包" aria-label="Permalink to “移除孤包”">​</a></h2><p>假如你想移除孤包，你需要安装 <code>deborphan</code> 软件：</p><p>在 Ubuntu 中安装 <code>deborphan</code> :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install deborphan</span></span></code></pre></div><h3 id="使用-deborphan" tabindex="-1">使用 deborphan <a class="header-anchor" href="#使用-deborphan" aria-label="Permalink to “使用 deborphan”">​</a></h3><p>打开终端并键入如下命令即可:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo deborphan | xargs sudo apt-get -y remove --purge</span></span></code></pre></div><h3 id="使用-gtkorphan-来移除孤包" tabindex="-1">使用 GtkOrphan 来移除孤包 <a class="header-anchor" href="#使用-gtkorphan-来移除孤包" aria-label="Permalink to “使用 GtkOrphan 来移除孤包”">​</a></h3><p><code>GtkOrphan</code> (一个针对 debian 系发行版本的 Perl/Gtk2 应用) 是一个分析用户安装过程状态并查找孤立库文件的图形化工具，它为 <code>deborphan</code> 提供了一个 GUI 前端，并具备移除软件包的功能。</p><h4 id="在-ubuntu-中安装-gtkorphan" tabindex="-1">在 Ubuntu 中安装 GtkOrphan <a class="header-anchor" href="#在-ubuntu-中安装-gtkorphan" aria-label="Permalink to “在 Ubuntu 中安装 GtkOrphan”">​</a></h4><p>打开终端并运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install gtkorphan</span></span></code></pre></div><h4 id="一张截图" tabindex="-1">一张截图 <a class="header-anchor" href="#一张截图" aria-label="Permalink to “一张截图”">​</a></h4><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/01/41.png" alt=""></p><h3 id="使用-wajig-移除孤包" tabindex="-1">使用 Wajig 移除孤包 <a class="header-anchor" href="#使用-wajig-移除孤包" aria-label="Permalink to “使用 Wajig 移除孤包”">​</a></h3><p><code>Wajig</code>是 Debian 包管理系统中一个简单的软件包管理前端。它将 apt、apt-cache、 dpkg、 /etc/init.d 中的脚本等 通过一个单一命令集成在一起，它的设计初衷是使用简单和为它的所有功能提供丰富的文档。</p><p>通过适当的 <code>sudo</code>配置，大多数（如果不是全部）的软件包安装和创建等任务可以通过一个用户 shell 来完成。<code>Wajig</code> 也适用于一般的系统管理。另外，一个 Gnome GUI 命令 <code>gjig</code>也被囊括在这个软件包之中。</p><h4 id="在-ubuntu-中安装-wajig" tabindex="-1">在 Ubuntu 中安装 Wajig <a class="header-anchor" href="#在-ubuntu-中安装-wajig" aria-label="Permalink to “在 Ubuntu 中安装 Wajig”">​</a></h4><p>打开终端并运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install wajig</span></span></code></pre></div><h2 id="debfoster-跟踪你在安装过程中的操作" tabindex="-1">Debfoster --- 跟踪你在安装过程中的操作 <a class="header-anchor" href="#debfoster-跟踪你在安装过程中的操作" aria-label="Permalink to “Debfoster --- 跟踪你在安装过程中的操作”">​</a></h2><p>debfoster 将会维护一个列有被明确需要安装的软件包的列表，但不包括那些作为某个软件的依赖而被安装的软件包。参数是完全可选的，你甚至可以使得在 dpkg 和/或 apt-get 每次运行之后马上激活 debfoster 。</p><p>另外，你还可以在命令行中使用 debfoster 来安装或移除某些特定的软件包。那些后缀为 <code>---</code> 的软件包将会被移除，而没有后缀的软件包将会被安装。</p><p>假如一个新的软件包或 debfoster 注意到作为某个软件包的依赖的软件包是一个孤包，则 debfoster 将会询问你下一步如何操作。若你决定保留这个孤包， debfoster 将只会进行记录并继续安装过程；若你觉得这个软件包不足以引起你的兴趣，在 debfoster 询问这个问题后，它将移除这个软件包。进一步的，如果你的决定使得其他的软件包变为孤包，更多的提问将会接踵而来。</p><h3 id="在-ubuntu-中安装-debfoster" tabindex="-1">在 Ubuntu 中安装 debfoster <a class="header-anchor" href="#在-ubuntu-中安装-debfoster" aria-label="Permalink to “在 Ubuntu 中安装 debfoster”">​</a></h3><p>打开终端并运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install debfoster</span></span></code></pre></div><h3 id="使用-debfoster" tabindex="-1">使用 debfoster <a class="header-anchor" href="#使用-debfoster" aria-label="Permalink to “使用 debfoster”">​</a></h3><p>为了创建一个初始跟踪文件，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo debfoster -q</span></span></code></pre></div><p>你总可以编辑 <code>/var/lib/debfoster/keepers</code> 文件，来定义那些你想留在系统中的软件包。</p><p>为了编辑这个文件，可以键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vi /var/lib/debfoster/keepers</span></span></code></pre></div><p>要强制使 debfoster 去移除所有没有被列在上面这个文件的软件包，或安装作为某些列在这个文件中的软件包的依赖，它也同时会添加所有在这个列表中没有被安装的软件包。若要根据这个列表来执行相关操作，只需执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo debfoster -f</span></span></code></pre></div><p>若需要跟踪你新安装的软件包，你需要时不时地执行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo debfoster</span></span></code></pre></div><h2 id="xdiskusage-查看你的硬盘空间都去哪儿了" tabindex="-1">xdiskusage -- 查看你的硬盘空间都去哪儿了 <a class="header-anchor" href="#xdiskusage-查看你的硬盘空间都去哪儿了" aria-label="Permalink to “xdiskusage -- 查看你的硬盘空间都去哪儿了”">​</a></h2><p>图形化地展示磁盘使用情况的 du。xdiskusage 是一个用户友好型的程序，它将为你展示你所有磁盘的使用情况。 它是在 Phillip C. Dykstra 所写的 “xdu” 程序的基础上设计的。做了一些修改以使得它可以为你运行 “du”命令，并显示磁盘的剩余空间，并且假如你想清晰地了解你的磁盘空间都去哪儿了，它还可以生成一个 PostScript 格式的名为 display.xdiskusage 的文件。</p><h3 id="在-ubuntu-中安装-xdiskusage" tabindex="-1">在 Ubuntu 中安装 xdiskusage <a class="header-anchor" href="#在-ubuntu-中安装-xdiskusage" aria-label="Permalink to “在 Ubuntu 中安装 xdiskusage”">​</a></h3><p>只需使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install xdiskusage</span></span></code></pre></div><p>若你想打开这个应用，你需要使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo xdiskusage</span></span></code></pre></div><p>一旦这个应用被打开，你将看到如下图所示的界面：</p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/01/5.png" alt=""></p><h2 id="bleachbit" tabindex="-1">Bleachbit <a class="header-anchor" href="#bleachbit" aria-label="Permalink to “Bleachbit”">​</a></h2><p>BleachBit 能快速地释放磁盘空间并不知疲倦地保护你的隐私。它可以释放缓存，删除 cookie，清除 Internet 上网历史，粉碎临时文件，删除日志，丢弃你所不知道存在何处的垃圾。为 Linux 和 Windows 系统而设计，它支持擦除清理数以千计的应用程序，如 Firefox, Internet Explorer, Adobe Flash, Google Chrome, Opera, Safari 等等。除了简单地删除文件，BleachBit 还包括许多高级功能，诸如粉碎文件以防止恢复，擦除磁盘空间来隐藏被其他应用程序所删除文件的痕迹，为火狐“除尘”，使其速度更快等。比免费更好，BleachBit 是一个开源软件。</p><h3 id="在-ubuntu-中安装-bleachbit" tabindex="-1">在 Ubuntu 中安装 Bleachbit <a class="header-anchor" href="#在-ubuntu-中安装-bleachbit" aria-label="Permalink to “在 Ubuntu 中安装 Bleachbit”">​</a></h3><p>打开终端并运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install bleachbit</span></span></code></pre></div><h3 id="一张截图-1" tabindex="-1">一张截图 <a class="header-anchor" href="#一张截图-1" aria-label="Permalink to “一张截图”">​</a></h3><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/01/6.png" alt=""></p><h3 id="使用-ubuntu-tweak" tabindex="-1">使用 Ubuntu-Tweak <a class="header-anchor" href="#使用-ubuntu-tweak" aria-label="Permalink to “使用 Ubuntu-Tweak”">​</a></h3>',75)),i("p",null,[e[4]||(e[4]=a("最后，你也可以使用 ",-1)),t(s,{href:"http://linux.cn/article-3335-1.html"},{default:l(()=>[...e[3]||(e[3]=[a("Ubuntu-Tweak",-1)])]),_:1}),e[5]||(e[5]=a(" 来清理你的系统。",-1))]),e[21]||(e[21]=i("hr",null,null,-1)),i("p",null,[e[7]||(e[7]=a("via: ",-1)),t(s,{href:"http://www.ubuntugeek.com/cleaning-up-a-ubuntu-gnulinux-system-updated-with-ubuntu-14-10-and-more-tools-added.html"},{default:l(()=>[...e[6]||(e[6]=[a("http://www.ubuntugeek.com/cleaning-up-a-ubuntu-gnulinux-system-updated-with-ubuntu-14-10-and-more-tools-added.html",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=a("作者：",-1)),t(s,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:l(()=>[...e[8]||(e[8]=[a("ruchi",-1)])]),_:1}),e[12]||(e[12]=a(" 译者：",-1)),t(s,{href:"https://github.com/FSSlc"},{default:l(()=>[...e[9]||(e[9]=[a("FSSlc",-1)])]),_:1}),e[13]||(e[13]=a(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...e[10]||(e[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=a("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[14]||(e[14]=[a("LCTT",-1)])]),_:1}),e[17]||(e[17]=a(" 原创翻译，",-1)),t(s,{href:"http://linux.cn/"},{default:l(()=>[...e[15]||(e[15]=[a("Linux中国",-1)])]),_:1}),e[18]||(e[18]=a(" 荣誉推出",-1))])])}const C=n(h,[["render",u]]);export{y as __pageData,C as default};
